DROP TABLE IF EXISTS `sys_oper_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_oper_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint NOT NULL COMMENT '租户ID【多租户隔离字段】',
  `title` varchar(100) DEFAULT NULL COMMENT '模块标题',
  `business_type` varchar(20) DEFAULT 'OTHER' COMMENT '业务类型:INSERT/UPDATE/DELETE/EXPORT/IMPORT/GRANT/SUBMIT/APPROVE/REJECT/OTHER',
  `method` varchar(500) DEFAULT NULL,
  `request_method` varchar(10) DEFAULT NULL COMMENT 'HTTP方法',
  `oper_url` varchar(500) DEFAULT NULL COMMENT '请求URL',
  `oper_ip` varchar(64) DEFAULT NULL COMMENT '操作IP',
  `oper_location` varchar(200) DEFAULT NULL COMMENT 'IP归属地',
  `oper_user_id` bigint DEFAULT NULL COMMENT '操作人用户ID',
  `oper_user_name` varchar(64) DEFAULT NULL COMMENT '操作人账号',
  `oper_dept_name` varchar(100) DEFAULT NULL COMMENT '操作人部门',
  `oper_param` text COMMENT '请求参数(脱敏后)',
  `json_result` text COMMENT '返回结果(截断)',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0成功 1失败',
  `error_msg` varchar(2000) DEFAULT NULL COMMENT '错误消息',
  `cost_time` bigint NOT NULL DEFAULT '0' COMMENT '耗时(毫秒)',
  `oper_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  `trace_id` varchar(64) DEFAULT NULL COMMENT '链路追踪ID，串联 ai_tool_call_log',
  PRIMARY KEY (`id`,`oper_time`),
  KEY `idx_tenant` (`tenant_id`),
  KEY `idx_tenant_time` (`tenant_id`,`oper_time`),
  KEY `idx_tenant_user` (`tenant_id`,`oper_user_id`),
  KEY `idx_tenant_type` (`tenant_id`,`business_type`),
  KEY `idx_oper_trace` (`trace_id`),
  KEY `idx_t_title_id` (`tenant_id`,`title`,`id`)
) ENGINE=InnoDB AUTO_INCREMENT=399 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='按月分区'
